/*getSysopOrderChangePoAfterHDPop*/
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = H.BUYER) AS BUYER_NAME, --[00] DECODE(H.DOC_TYPE,'S','(선입고)','F','(긴급발주)','') DOC_TEXT, --[01] (SELECT C2.TEXT1 FROM ICOMCOD2 C2 WHERE C2.TYPE = 'C001' AND C2.COMPANY_CODE = H.BUYER AND C2.CODE = R.PURCHASER_DEPT) AS PO_DEPT_NAME, --[02] (SELECT C2.TEXT1 FROM ICOMCOD2 C2 WHERE C2.TYPE = 'C001' AND C2.COMPANY_CODE = H.BUYER AND C2.CODE = R.REQ_DEPT) AS REQ_DEPT_NAME, --[03] H.PO_NO AS PO_NO, --[04] H.PURCHASER_NAME AS PO_USER_NAME, --[05] (SELECT L.USER_NAME_LOC FROM ICOMLUSR L WHERE L.COM_CODE = H.BUYER AND L.USER_ID = R.REQ_USER_ID) AS REQ_USER_NAME, --[06] H.PO_CREATE_DATE, --[07] H.AGENT_PO_TTL_AMT AS AGENT_AMT, --[08] H.PO_TTL_AMT AS PO_AMT, --[09] H.DELY_TO_LOCATION AS DELY, --[10] H.PO_REMARK AS REMARK, --[11] H.DOC_TYPE, --[12] H.BUYER, --[13] R.PURCHASER_DEPT, --[14] R.REQ_DEPT, --[15] H.PURCHASER_ID, --[16] R.REQ_USER_ID, --[17] (SELECT '( '||TEXT2||' )' FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = H.PROCESS_TYPE) AS PROCESS_TEXT --[18]
FROM ICOMPOHD H, ICOMPODT D, ICOMPRDT R WHERE H.BUYER = #{value} AND H.PO_NO = #{value} AND H.BUYER = D.BUYER AND H.PO_NO = D.PO_NO AND D.BUYER = R.BUYER AND D.PR_NO = R.PR_NO AND D.PR_SEQ = R.PR_SEQ AND H.STATUS <> 'D' AND D.STATUS <> 'D' AND R.STATUS <> 'D'

mapper.update:
/*setSysopOrderChangeAfterSave1*/
UPDATE ICOMPRDT SET STATUS = 'R', SELLER_ITEM_NO = #{value}, REF_PR_NO = #{value}, CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'), MAKER_NAME = #{value}, MAKER_CODE = #{value},
DESCRIPTION = #{value}, SPECIFICATION = #{value}, UNIT_MEASURE = #{value},
CMS_CATLG_ID = #{value}, CMS_CATEG_ID = #{value}
WHERE BUYER = #{value} AND PR_NO = #{value} AND PR_SEQ = #{value} AND STATUS != 'D'

/*setSysopOrderChangeAfterSave3*/
UPDATE ICOMIVDT SET STATUS = 'R', SELLER_ITEM_NO= #{value}, REF_PR_NO = #{value}, CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'), MAKER_NAME = #{value}, MAKER_CODE = #{value},
DESCRIPTION = #{value}, SPECIFICATION = #{value}, UNIT_MEASURE = #{value}, ORIGIN_CODE = #{value}
WHERE BUYER = #{value} AND PO_NO = #{value} AND PO_SEQ = #{value} AND STATUS != 'D'

/*setSysopOrderChangeAfterSave4*/

              UPDATE ICOMPORS
                 SET STATUS= 'R',
                     SELLER_ITEM_NO = #{value},
                     CHANGE_DATE    = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                     CHANGE_TIME    = TO_CHAR(SYSDATE, 'HH24MISS'),
     DESCRIPTION= #{value},
     SPECIFICATION  = #{value},
     UNIT_MEASURE= #{value}
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}
               AND STATUS != 'D'

/*setSysopOrderChangeAfterAgentModify1*/
UPDATE ICOMPRDT SET AGENT = #{value} , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
MAKER_CODE=#{value}, MAKER_NAME=#{value}, LIST_PRICE=#{value}, CMS_CATLG_ID=#{value}, CMS_CATEG_ID=#{value}
WHERE BUYER = #{value} AND PR_NO = #{value} AND PR_SEQ = #{value}

mapper.select:
/*getGrApBillInfo*/

    SELECT DECODE(COUNT(PO_SEQ),0,'N','Y') AS AP_BILL_YN    
   FROM ICOMGRDT        
   WHERE BUYER =  #{value}       
   AND PO_NO   =  #{value}    
   AND PO_SEQ  = #{value}    
   AND STATUS != 'D'   
   AND (AP_BILL_FLAG = 'Y'  OR  AR_BILL_FLAG = 'Y'  OR CLOSE_FLAG = 'Y' OR CLOSE_DATE > GR_DATE)

