/*setSysopOrderChangeAfterRdDate2*/

            UPDATE ICOMPODT
               SET STATUS       = 'R',
       RD_DATE= #{value} ,
       SEND_DATE= ' ',
       SEND_TIME= ' ',
                   CHANGE_DATE  = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME  = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}

/*setSysopOrderChangeAfterRdDate3*/

UPDATE ICOMPOIF_DOOSAN        
   SET RD_DATE        = #{value}
 WHERE LEGACY_PO_NO   = #{value}
   AND LEGACY_PO_SEQ  = #{value}

/*setSysopOrderChangeAfterPoInit1*/

            UPDATE ICOMPRDT
               SET STATUS        = 'R'
             WHERE BUYER   = #{BUYER}
               AND PR_NO   = #{PR_NO}
               AND STATUS != 'D'

/*setSysopOrderChangeAfterPoInit3*/

            UPDATE ICOMPORS
               SET  STATUS        = 'D',
                    CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                    CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
              WHERE BUYER   = #{BUYER}
                AND PO_NO   = #{PO_NO}
                AND STATUS != 'D'

/*setSysopOrderChangeAfterPoInit5*/

             UPDATE ICOMPRHD 
                SET STATUS = DECODE((SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = #{BUYER}  AND PR_NO = #{PR_NO}  AND STATUS IN ('C','R')),0,'D','R'),  
                    CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                    CHANGE_TIME   = TO_CHAR(SYSDATE,'HH24MISS')
              WHERE BUYER = #{BUYER}
                AND PR_NO = #{PR_NO}

/*setSysopOrderChangeAfterPrice1*/

            UPDATE ICOMPRDT
               SET STATUS        = 'R',           
       TARGET_PRICE  = #{value},
                   LIST_PRICE    = #{value},
       CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PR_NO   = #{value}
               AND PR_SEQ  = #{value}

/*setSysopOrderChangeAfterPrice3*/

            UPDATE ICOMIVDT                                                 
               SET STATUS        = 'R',                                     
                   UNIT_PRICE    = #{value},
                   ITEM_AMT = TRUNC( #{value} * INV_QTY,2),
                   CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}
               AND STATUS != 'D'

/*setSysopOrderChangeAfterPrice4*/

            UPDATE ICOMGRDT
               SET STATUS= 'R',
               UNIT_PRICE= #{value},
               AGENT_PRICE= #{value},
               ITEM_AMT= ROUND(ITEM_QTY * #{value}),
               AGENT_ITEM_AMT= ROUND(ITEM_QTY * #{value}),
                   CHANGE_DATE= TO_CHAR(SYSDATE, 'YYYYMMDD'),
                   CHANGE_TIME= TO_CHAR(SYSDATE, 'HH24MISS')
             WHERE BUYER   = #{value}
               AND PO_NO   = #{value}
               AND PO_SEQ  = #{value}
               AND AP_BILL_FLAG  = 'N'
